"""Load the pose library generated by poses/posegen.py (copied to app/data/poses.json)."""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path

LIBRARY_PATH = Path(__file__).resolve().parent.parent / "data" / "poses.json"


@lru_cache(maxsize=1)
def get_library() -> dict:
    with LIBRARY_PATH.open(encoding="utf-8") as handle:
        return json.load(handle)


def get_pose(pose_id: str) -> dict | None:
    return next((p for p in get_library()["poses"] if p["id"] == pose_id), None)
